import sys
from datetime import datetime, timedelta


def parse_time(s: str) -> datetime:
    return datetime.strptime(s, "%H:%M")


def overlaps(a_start: datetime, a_end: datetime, b_start: datetime, b_end: datetime) -> bool:
    return a_start < b_end and b_start < a_end


def main():
    bookings = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "book":
            if len(parts) != 6:
                continue
            bid, room, day, start_str, end_str = parts[1], parts[2], parts[3], parts[4], parts[5]
            try:
                start = parse_time(start_str)
                end = parse_time(end_str)
            except ValueError:
                print(f"INVALID {bid}")
                continue
            if end <= start:
                print(f"INVALID {bid}")
                continue
            conflict = None
            for other_bid, other_room, other_day, other_start, other_end in bookings:
                if other_room == room and other_day == day and overlaps(
                    start, end, other_start, other_end
                ):
                    if conflict is None or other_start < bookings[conflict][3]:
                        conflict = bookings.index((other_bid, other_room, other_day, other_start, other_end))
            if conflict is not None:
                print(f"REJECT {bid} {bookings[conflict][0]}")
            else:
                bookings.append((bid, room, day, start, end))
                print(f"ACCEPT {bid}")
        elif parts[0] == "cancel":
            if len(parts) != 2:
                continue
            bid = parts[1]
            new_bookings = []
            found = False
            for b in bookings:
                if b[0] == bid:
                    found = True
                else:
                    new_bookings.append(b)
            if not found:
                print(f"UNKNOWN {bid}")
            else:
                bookings = new_bookings
                print(f"CANCELLED {bid}")
        else:
            continue

    rooms = {}
    for bid, room, day, start, end in bookings:
        rooms[room] = rooms.get(room, {"count": 0, "total": timedelta()} )
        rooms[room]["count"] += 1
        rooms[room]["total"] += end - start

    for room in sorted(rooms):
        count = rooms[room]["count"]
        total = rooms[room]["total"]
        hours = int(total.total_seconds() / 3600)
        minutes = int((total.total_seconds() % 3600) / 60)
        print(f"{room} {count} {f'{hours}:{minutes:02}'}")
